   applyNative(l=>{if(draft.attack!==l.tactics[l.userSide])setLiveTactic(draft.attack);if(draft.defence&&draft.defence!==l.defences?.[l.userSide])setLiveDefence(draft.defence);if(draft.policy!==l.penaltyPolicies?.[l.userSide]&&typeof setPenaltyPolicy==='function')setPenaltyPolicy(draft.policy);if(draft.playbook&&playbookRules(l)){const previousZone=playbookZone;try{for(const zone of Object.keys(FIELD_ZONES)){playbookZone=zone;for(const kind of ['attack','defence'])if(draft.playbook.zones[zone][kind]!==l.playbooks[l.userSide].zones[zone][kind])setPlaybookChoice(kind,draft.playbook.zones[zone][kind]);}for(const kind of ['scrum','lineout','kickoff'])if(draft.playbook[kind]!==l.playbooks[l.userSide][kind])setPlaybookChoice(kind,draft.playbook[kind]);}finally{playbookZone=previousZone;}}});
